from pathlib import Path
p = Path('lib/ansible/executor/module_common.py')
s = p.read_text()
a = s.index('def recursive_finder(')
b = s.index('\\ndef _is_binary(', a)
new = r'''def recursive_finder(name, module_fqn, data, py_module_names, py_module_cache, zf):
    \"\"\"Resolve and bundle module_utils dependencies using a work queue.\"\"\"
    module_utils_paths = [p for p in module_utils_loader._get_paths(subdirs=False) if os.path.isdir(p)]
    module_utils_paths.append(_MODULE_UTILS_PATH)
    pending = deque([(name, module_fqn, data)])
    examined = set()
    added = set()

    while pending:
        current_name, current_fqn, current_data = pending.popleft()
        if current_fqn in examined:
            continue
        examined.add(current_fqn)
        try:
            tree = compile(current_data, '<unknown>', 'exec', ast.PyCF_ONLY_AST)
        except (SyntaxError, IndentationError) as e:
            raise AnsibleError(\"Unable to import %s due to %s\" % (current_name, e.msg))
        finder = ModuleDepFinder(current_fqn)
        finder.visit(tree)

        for imported in sorted(finder.submodules):
            if imported[:3] == ('ansible', 'module_utils', 'six') or imported[:3] == ('ansible', 'module_utils', '_six'):
                imported = ('ansible', 'module_utils', 'six')
            if imported in py_module_names:
                continue
            if imported[:2] == ('ansible', 'module_utils'):
                locator = LegacyModuleUtilLocator(imported, is_ambiguous=len(imported[2:]) > 1,
                                                  mu_paths=module_utils_paths)
                if not locator.found:
                    for fq_candidate in locator.candidate_names_joined():
                        try:
                            redirect_info = InternalRedirectModuleInfo(fq_candidate.rsplit('.', 1)[-1], fq_candidate)
                        except ImportError:
                            continue
                        locator.found = locator.redirected = True
                        locator.name_parts = tuple(fq_candidate.split('.'))
                        locator.source = redirect_info.get_source()
                        locator.output_path = redirect_info.path
                        break
            elif imported[0] == 'ansible_collections':
                locator = CollectionModuleLocator(imported, is_ambiguous=len(imported) > 6)
            else:
                continue

            if not locator.found:
                raise AnsibleError('Could not find imported module support code for {0}. Looked for ({1})'.format(
                    '.'.join(imported), locator.candidate_names_joined()))

            resolved = tuple(locator.name_parts)
            if locator.is_package:
                cache_name = resolved + ('__init__',)
                output_path = os.path.join(*resolved, '__init__.py')
            else:
                cache_name = resolved
                output_path = os.path.join(*resolved) + '.py'
            if cache_name not in added and cache_name not in py_module_names:
                py_module_cache[cache_name] = (locator.source, output_path)
                pending.append((cache_name[-1], '.'.join(cache_name), locator.source))
                added.add(cache_name)

            # Collection trees may omit __init__.py at any package level.
            if resolved[0] == 'ansible_collections':
                for idx in range(1, len(resolved)):
                    init_name = resolved[:idx] + ('__init__',)
                    if init_name not in added and init_name not in py_module_names:
                        init_path = os.path.join(*resolved[:idx], '__init__.py')
                        py_module_cache[init_name] = (b'', init_path)
                        pending.append(('__init__', '.'.join(init_name), b''))
                        added.add(init_name)

    # The wrapper imports basic unconditionally to inject module arguments.
    basic_name = ('ansible', 'module_utils', 'basic')
    if basic_name not in py_module_names and basic_name not in added:
        basic = ModuleInfo('basic', module_utils_paths)
        py_module_cache[basic_name] = (basic.get_source(), basic.path)
        pending.append(('basic', '.'.join(basic_name), basic.get_source()))
        added.add(basic_name)
        # Resolve basic's own dependencies through the same queue.
        while pending:
            current_name, current_fqn, current_data = pending.popleft()
            if current_fqn in examined:
                continue
            examined.add(current_fqn)
            try:
                tree = compile(current_data, '<unknown>', 'exec', ast.PyCF_ONLY_AST)
            except (SyntaxError, IndentationError) as e:
                raise AnsibleError(\"Unable to import %s due to %s\" % (current_name, e.msg))
            finder = ModuleDepFinder(current_fqn)
            finder.visit(tree)
            # Re-enter the public queue processor without recursion by appending
            # work to the existing dependency set below.
            for imported in finder.submodules:
                if imported not in py_module_names and imported not in added:
                    pending.append((imported[-1], '.'.join(imported), b''))

    for cache_name, (source, path) in list(py_module_cache.items()):
        if cache_name in py_module_names:
            continue
        zf.writestr(os.path.join(*cache_name) + '.py', source)
        py_module_names.add(cache_name)
        display.vvvvv(\"Using module_utils file %s\" % to_text(path, errors='surrogate_or_strict'))
    py_module_cache.clear()

    for path in ('ansible/__init__.py', 'ansible/module_utils/__init__.py'):
        try:
            zf.getinfo(path)
        except KeyError:
            zf.writestr(path, b'')
'''
p.write_text(s[:a] + new + s[b:])
PY
"

